-- Rifts World Book 34: Northern Gun Two, four hovercycles (printed 161-166): Cobra Turbo, Hornet, Jouster, Magnum-Turbo
-- 4 vehicle rows, with 39 locations and 7 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~315-northern-gun-2-hovercycles-a.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('ng-488-cobra-turbo-hovercycle', 'NG-488 Cobra Turbo Combat Hovercycle', 'rifts', 'vehicle', 'One rider.', 'One, behind the rider; uncomfortable on long trips.', NULL, 'Maximum 235 mph (376 km). Maximum altitude 100 ft (30.5 m); handles drops from up to 800 ft (244 m). VTOL to 200 ft (61 m) on the pivoting tail thruster. A hover vehicle; the book prints one speed.', NULL, 'Height 4 ft (1.2 m); length 12 ft (3.6 m); width 3 ft (0.9 m)', '1,350 lbs (607.5 kg)', 150, 1, NULL, 255000, '255,000 credits gasoline, 375,000 electric, 1.3 million nuclear with a 10 year life; the lowest is stored. The triple-barrel nose laser is part of the bike; optional weapons cost extra and are never discounted.', 'Model NG-488, new (Vehicle Type: Hovercycle). A large, aggressive-looking combat bike with a prominent nose gun and a long body ending in jet thrusters, banned in most civilized places, the Coalition States included. Heavily armoured for its class, fast and nimble, dependable and needing little upkeep, it has VTOL, hovers in place and takes dead drops and leapfrogging with ease; combat cyborgs, Crazies, Juicers, Headhunters, robot pilots and mercenaries favour it. Its big tail thruster pivots up and down for higher jumps, leapfrogs, wheelies, sudden speed bursts (the City Rats'' rocket launch) and VTOL to 200 ft (61 m); pointed straight down with the brakes on, it turns the bike a full circle in two seconds at any speed (the tornado donut spin). +1 on initiative and +1 to dodge, and it halves its penalties on sudden stops, jumps, leapfrogs and dead drops. Penalties: -10% piloting in the best conditions for its nose gun, weight, size and power, a further -10% for evasive action or stunts; each optional weapon cuts speed and altitude by 5%. Optional weapons: any modular hovercycle system (the NG-HM10 to NG-WS604 gear rows), one at the back and one on each side. Radar tracker: follows 42 airborne targets (missiles, aircraft, power armor, Xiticix) out to 40 miles (64 km); its comms array picks up commercial and police radio and serves as a 5 mile (8 km) two-way radio, linkable to helmet radios and HUDs. Dealers push the Viper ride armor with it. Marked small targets need a Called Shot at -5 to strike, and the crouched rider is as hard to hit. Maximum range 850 miles (1,360 km) on fuel or electric, unlimited on nuclear. Engine: usually combustion or electric, nuclear available. Never bought or used by the CS.', 'Rifts World Book 34: Northern Gun Two p.161-162'),
  ('ng-424-hornet-hovercycle', 'NG-424 Hornet Combat Hovercycle', 'rifts', 'vehicle', 'One rider.', 'None; no space for a passenger.', NULL, 'Maximum 200 mph (320 km). Maximum altitude 60 ft (18.3 m); handles drops of up to 800 ft (244 m). Not built to fly: -10% piloting per 50 ft (15.2 m) above the ground. A hover vehicle; the book prints one speed.', NULL, 'Height 3.9 ft (1.19 m); length 12 ft (3.7 m); width 3.3 ft (1 m) unarmed, 5.7 ft (1.7 m) with the usual pair of eight-shot missile pods', '942 lbs (424 kg)', 122, 1, NULL, 195000, '195,000 credits gasoline, 255,000 electric, 735,000 Solid Oxide, 995,500 nuclear with a 10 year life; the lowest is stored. Every weapon, the common loadout included, costs extra and is never discounted.', 'Model NG-424, new (Vehicle Type: Combat Hovercycle). A close relative of the NG-400 Stinger in looks and design, but built of newer, lighter M.D.C. materials, quicker and harder-hitting. It takes any hovercycle weapons; the usual fit is a dual system in a basic nose turret pairing an NG-HI16 ion blaster with an NG-HL20 laser, plus an NG-MM68 missile pod on each side, a loadout so widespread that many take it for standard. Its fame owes much to RoboDome gladiator Todd "The Hornet" Spencley, who won races and arena bouts on that fit and fronted NG''s advertising, then vanished days after humiliating a Federation of Magic mage who would not pay a street-race debt; his battered bike was found near a bar with "Loser" painted on it, and the unsolved mystery keeps sales up. The Ishpeming Police ride a faster interceptor version capable of true flight at 300 mph (480 km), not sold to the public. Low profile: +1 to dodge. Penalties: -5% piloting for sudden stops or elaborate stunts; the pair of pods costs -20% piloting and 20% of top speed; each extra weapon cuts speed by 5%. Marked small targets need a Called Shot at -5 to strike, and so does the crouched rider. Range: 1,000 miles (1,600 km). Power: usually combustion or electric, nuclear available; a Solid Oxide version is priced. Bought by the CS military and the ISS police.', 'Rifts World Book 34: Northern Gun Two p.162-163'),
  ('ng-277-jouster-hovercycle', 'NG-277 Jouster Combat Hovercycle', 'rifts', 'vehicle', 'One rider.', 'None; no space for a passenger.', NULL, 'Maximum 290 mph (464 km). Maximum altitude 1,000 ft (305 m), though it usually hovers 3-12 ft (0.9 to 3.6 m) up; handles drops of up to 2,000 ft (610 m). -5% piloting per 200 ft (61 m) above the ground. A hover vehicle; the book prints one speed.', NULL, 'Height 6 ft (1.8 m); length 17 ft overall, 14 ft (4.3 m) nose to thruster plus 3 ft (0.9 m) of lance; wingspan 14 ft (4.3 m)', '980 lbs (432 kg)', 128, 1, NULL, 369000, '369,000 credits gasoline, 445,000 electric, 825,000 Solid Oxide, 1.4 million nuclear with a 10 year life; the lowest is stored. The lance, nose gun and wing sponsons are standard; added weapons cost extra and are never discounted.', 'Model NG-277, new (Vehicle Type: Winged Combat Hovercycle). One of three winged designs led by Andy "Fly Boy" McElvary that borrow from aircraft, this one with help from Benjamin Bonds and Leigh O''Neil. Short wings, a bigger tail fin and extra thrusters above the wings make it steadier and more aerodynamic at speed; it has the largest wings of the line and, alone among them, climbs well above normal hovercycle height, riding strong winds almost like a low-level one-man flyer. It glides in quietly with little more than engine hum and wind noise, is sturdy and low-maintenance, and has VTOL and hover. Its jumps are the highest and longest of any hovercycle, triple other bikes on dead drops and leapfrogs, but the heavy nose must be kept up: if it strikes the ground (3D6 M.D. to the main body), on 01-50% it bounces and either carries on 1D4x10 yards/meters before settling or spins out (-15% piloting). The wings bar narrow alleys and forests unless the bike is tipped on its side, wings vertical, narrowing it to 6 ft (1.8 m) as trick driving (-10%); City Rats, Crazies and Juicers ride narrow streets that way to show off, and riders hold jousting duels with its lance. It shines on open plains and deserts. Dodge: +1 under 100 mph (160 km), +2 at 101-200 mph (161.6-320 km), +3 faster. Penalties: -5% piloting for sudden stops, tricks, stunts or evasion; none for the built-in weapons. Losing one wing: -10% speed and -12% piloting; both: -20% speed and -24% piloting. Losing a wing thruster with its wing intact: -10% speed, -5% piloting. Weapons or cargo strapped to the wings cost 10-25% of speed; one optional weapon may go on each front side at 5% of speed each. Marked small targets need a Called Shot at -5 to strike, as does the crouched rider. Range: 1,200 miles (1,920 km). Power: usually combustion or electric, nuclear available; a Solid Oxide version is priced. Never bought by the CS military; very popular with city riders, racers and people in open country.', 'Rifts World Book 34: Northern Gun Two p.164-165'),
  ('ng-357-magnum-turbo-hovercycle', 'NG-357 Magnum-Turbo Hovercycle', 'rifts', 'vehicle', 'One rider.', 'One, behind the rider; uncomfortable on long trips.', NULL, 'Maximum 205 mph (328 km). Maximum altitude 100 ft (30.5 m); handles drops from as high as 400 ft (122 m). VTOL to 200 ft (61 m) on the angled rear thruster; -10% piloting per 30 ft (9.1 m) above the ground. A hover vehicle; the book prints one speed.', NULL, 'Height 4 ft (1.2 m); length 9 ft (2.7 m); width 3.5 ft (1.07 m)', '1,300 lbs (585 kg)', 175, 1, NULL, 166000, '166,000 credits gasoline, 245,000 electric, 798,000 Solid Oxide, 1.3 million nuclear with a 10 year life; the lowest is stored. Weapons cost extra and are never discounted.', 'Model NG-357 (Vehicle Type: Hovercycle), the Cobra Turbo''s heavily armoured cousin: a big tricked-out hog, noisy and flashy, fast and handy for its bulk, dependable and low-maintenance, with VTOL, hover and big drops; favoured by combat cyborgs, Crazies, Juicers, Headhunters, robot pilots and mercenaries. Its rear jet angles for better jumps, wheelies, rocket-launch bursts of speed and VTOL to 200 ft (61 m), and pointed straight down with the brakes on it gives the two-second tornado donut spin at any speed. +1 on initiative and +1 to dodge, and it halves its penalties on sudden stops, jumps, leapfrogs and dead drops. Penalties: -10% piloting in the best conditions for its weight, size and power, a further -15% for evasive action or stunts. No built-in weapons: any modular hovercycle system may be added, each costing 5% of top speed. The penalties paragraph allows up to two at the front (over the front hover jet, and high on the nose under the windshield), one at the back and one per side; the weapons paragraph says one in the nose. Marked small targets need a Called Shot at -3 to strike, as does the crouched rider. Maximum range 500 miles (800 km) on fuel or electric, unlimited on nuclear. Engine: usually combustion or electric, Solid Oxide and nuclear available. Never bought or used by the CS.', 'Rifts World Book 34: Northern Gun Two p.165-166');

