INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-488-cobra-turbo-hovercycle', 1, 'NG-424 Stinger Triple Barrel Nose Gun (medium laser)', '2D6 M.D. single shot, 4D6 M.D. double blast, 6D6 M.D. triple blast at one target', 1, '2,000 ft (610 m)', 'Each single, double or triple blast is one melee attack', '40 triple blasts, one E-Clip per laser; unlimited on nuclear power', NULL, 'Exclusive to the Cobra Turbo. A somewhat experimental three-barrel laser in a ball turret that replaces the nose, turning 45 degrees forward, up, down and to either side, unlike the fixed forward guns of most hovercycles. The book prints the model number NG-424, which is also the Hornet''s.'),
  ('ng-424-hornet-hovercycle', 1, 'NG-HI16 Medium-Range Ion Blaster', '3D6 M.D. per blast', 1, '1,200 ft (366 m)', 'Single shot; each counts as one melee attack', '12 shots per E-Clip', NULL, 'Common loadout, not standard: bought separately (gear row ng-hi16-medium-range-ion-blaster) and paired with the laser below in a basic nose turret. The Hornet entry calls it the NG-HI16 Medium Ion Blaster.'),
  ('ng-424-hornet-hovercycle', 2, 'NG-HL20 Long-Range Medium Laser', '2D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Single shot; each counts as one melee attack', '20 shots per E-Clip', NULL, 'Common loadout, not standard: bought separately (gear row ng-hl20-long-range-medium-laser) and paired with the ion blaster above in a basic nose turret.'),
  ('ng-424-hornet-hovercycle', 3, 'NG-MM68 Mini-Missile Pod Launcher', 'By mini-missile type', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 4 or 6', 'Eight mini-missiles per pod, 16 for the pair', NULL, 'Common loadout, not standard: one pod on each side, bought separately (gear row ng-mm68-mini-missile-pod-launcher). The pair costs -20% piloting and 20% of top speed.'),
  ('ng-277-jouster-hovercycle', 1, 'NG-JL277 Joust Lance', '1D6 M.D. or 2D6 M.D. (two settings)', 1, '3,000 ft (914 m)', 'Each shot is one melee attack', '20 full-power shots per E-Clip; two E-Clip ports standard for 40. Unlimited on a nuclear power supply', NULL, 'Exclusive to the Jouster. A precision long-range laser whose thick, strong barrel doubles as a real jousting lance for knocking riders off hovercycles, rocket bikes or riding animals. It has 100 M.D.C. and sits on a swivel above the handlebars, turning 45 degrees left and right and spinning a full 360 degrees, so it fires forward or back at ground and air targets. A rider of second level or higher with the Hovercycle skill can swing it rearward at full throttle and fire at pursuers (Shooting Wild). Called Shots only when stopped, hovering or under 30 mph (48 km). Cowboys use it to prod cattle. Standard; it would sell for 75,000 credits if NG ever offered it as a modular option.'),
  ('ng-277-jouster-hovercycle', 2, 'NG-HI18 Heavy Ion Blaster', '4D6 M.D. per blast', 1, '1,200 ft (366 m)', 'Single shot; each counts as one melee attack', '6 shots per E-Clip. Unlimited on a nuclear power supply', NULL, 'The nose gun, in a small ball turret with 90 degree rotation; the entry calls it the NG-HI18 Heavy Ion Blaster Nose Gun. Standard on the Jouster; in a ball turret it normally sells for 60,000 credits (gear row ng-hi18-heavy-ion-blaster).'),
  ('ng-277-jouster-hovercycle', 3, 'NG-WS604 Wing Sponson Missile Cluster', 'By mini-missile type', 1, 'One mile (1.6 km), per the modular weapon list', '1, 2 or 4 mini-missiles', 'Four mini-missiles per wing, eight total', NULL, 'One sponson per wing, standard. The entry calls them Wing Sponsons and prints no model number; the name is the modular sponson cluster''s (gear row ng-ws604-wing-sponson-missile-cluster), and the range and rate of fire come from that entry.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-488-cobra-turbo-hovercycle', 'ng-424-hornet-hovercycle', 'ng-277-jouster-hovercycle', 'ng-357-magnum-turbo-hovercycle');
SELECT 'their 39 locations are in' AS assertion, count(*) AS got, 39 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-488-cobra-turbo-hovercycle', 'ng-424-hornet-hovercycle', 'ng-277-jouster-hovercycle', 'ng-357-magnum-turbo-hovercycle');
SELECT 'their 7 weapon entries are in' AS assertion, count(*) AS got, 7 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-488-cobra-turbo-hovercycle', 'ng-424-hornet-hovercycle', 'ng-277-jouster-hovercycle', 'ng-357-magnum-turbo-hovercycle');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-488-cobra-turbo-hovercycle', 'ng-424-hornet-hovercycle', 'ng-277-jouster-hovercycle', 'ng-357-magnum-turbo-hovercycle') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~315-northern-gun-2-hovercycles-a.sql');
